        "fact_id": {
          "pattern": "^FACT-[0-9]{3,}$",
          "title": "Fact Id",
          "type": "string"
        },
        "statement": {
          "maxLength": 1000,
          "minLength": 1,
          "title": "Statement",
          "type": "string"
        },
        "block_ids": {
          "items": {
            "type": "string"
          },
          "maxItems": 4,
          "minItems": 1,
          "title": "Block Ids",
          "type": "array"
        },
        "is_uncertain": {
          "default": false,
          "title": "Is Uncertain",
          "type": "boolean"
        },
        "attributes": {
          "$ref": "#/$defs/FactAttributes",
          "description": "Optional field-specific values copied from the same evidence. Only communications and components use the reviewed keys validated by FieldExtractionResult.",
          "title": "Attributes"
        }
      },
      "required": [
        "fact_id",
        "statement",
        "block_ids"
      ],
      "title": "RetrievedFact",
      "type": "object"
    }
  },
  "additionalProperties": false,
  "description": "Compact persisted candidate facts for one Node/field slice.",
  "properties": {
    "node_id": {
      "type": "string",
      "const": "node_1"
    },
    "field_id": {
      "type": "string",
      "const": "operational_environment"
    },
    "facts": {
      "items": {
        "$ref": "#/$defs/RetrievedFact"
      },
      "maxItems": 12,
